module GemIslandSim #(\n    parameter MAX_N = 8,\n    parameter MAX_D = 16,\n    parameter MAX_R = 8,\n    parameter DATA_WIDTH = 8,\n    parameter RESULT_WIDTH = 32\n)(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [7:0] d,\n    input [3:0] r,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE  = 4'd0;\n    localparam [3:0] INIT  = 4'd1;\n    localparam [3:0] SPLIT = 4'd2;\n    localparam [3:0] SORT  = 4'd3;\n    localparam [3:0] DONE_STATE = 4'd4;\n\n    // Internal registers\n    reg [3:0] state, next_state;\n    reg [7:0] counts [0:MAX_N-1];\n    reg [7:0] current_night;\n    reg [15:0] lfsr;\n    reg [7:0] night_count;\n    reg [7:0] total_gems;\n    reg [15:0] rand_num;\n    reg [7:0] split_index;\n    reg [7:0] max_index;\n    reg [7:0] max_value;\n    reg [7:0] sort_counter;\n    reg [7:0] sum_counter;\n    reg [31:0] temp_sum;\n    reg [7:0] i, j;\n    reg [7:0] cumulative;\n    reg found;\n\n    // LFSR polynomial: 16'hD008 (taps at 16,15,13,4)\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            lfsr <= 16'h0001;\n        end else if (state == SPLIT) begin\n            lfsr <= {lfsr[14:0], lfsr[15] ^ lfsr[14] ^ lfsr[12] ^ lfsr[3]};\n        end\n    end\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            current_night <= 8'd0;\n            night_count <= 8'd0;\n            total_gems <= 8'd0;\n            rand_num <= 16'd0;\n            split_index <= 8'd0;\n            max_index <= 8'd0;\n            max_value <= 8'd0;\n            sort_counter <= 8'd0;\n            sum_counter <= 8'd0;\n            temp_sum <= 32'd0;\n            i <= 8'd0;\n            j <= 8'd0;\n            cumulative <= 8'd0;\n            found <= 1'b0;\n            for (j = 0; j < MAX_N; j = j + 1) begin\n                counts[j] <= 8'd0;\n            end\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = INIT;\n                end\n            end\n            INIT: begin\n                if (i == n) begin\n                    next_state = SPLIT;\n                end\n            end\n            SPLIT: begin\n                if (current_night == d) begin\n                    next_state = SORT;\n                end\n            end\n            SORT: begin\n                if (sort_counter == r) begin\n                    next_state = DONE_STATE;\n                end\n            end\n            DONE_STATE: begin\n                next_state = IDLE;\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Datapath logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialization handled above\n        end else begin\n            case (state)\n                INIT: begin\n                    if (i < n) begin\n                        counts[i] <= 8'd1;\n                        i <= i + 8'd1;\n                    end\n                end\n                SPLIT: begin\n                    if (current_night < d) begin\n                        total_gems <= n + night_count;\n                        rand_num <= (lfsr % total_gems) + 1;\n                        cumulative <= 8'd0;\n                        found <= 1'b0;\n                        j <= 8'd0;\n                        split_index <= 8'd0;\n                    end else begin\n                        current_night <= current_night + 8'd1;\n                        night_count <= night_count + 8'd1;\n                    end\n                end\n                SORT: begin\n                    if (sum_counter < r) begin\n                        if (j < n) begin\n                            if (counts[j] > max_value) begin\n                                max_value <= counts[j];\n                                max_index <= j;\n                            end\n                            j <= j + 8'd1;\n                        end else begin\n                            temp_sum <= temp_sum + max_value;\n                            counts[max_index] <= 8'd0;\n                            max_value <= 8'd0;\n                            j <= 8'd0;\n                            sum_counter <= sum_counter + 8'd1;\n                        end\n                    end\n                end\n                DONE_STATE: begin\n                    result <= temp_sum;\n                    done <= 1'b1;\n                end\n                default: begin\n                    done <= 1'b0;\n                end\n            endcase\n        end\n    end\n\n    // Find split index\n    always @(*) begin\n        if (state == SPLIT && current_night < d) begin\n            cumulative = 8'd0;\n            found = 1'b0;\n            for (i = 0; i < n; i = i + 1) begin\n                if (!found) begin\n                    cumulative = cumulative + counts[i];\n                    if (cumulative >= rand_num) begin\n                        split_index = i;\n                        found = 1'b1;\n                    end\n                end\n            end\n        end\n    end\n\n    // Increment split index count\n    always @(posedge clk) begin\n        if (state == SPLIT && current_night < d && found) begin\n            counts[split_index] <= counts[split_index] + 8'd1;\n        end\n    end\n\n    // Update sort counter\n    always @(posedge clk) begin\n        if (state == SORT && sum_counter < r && j == n && max_value != 8'd0) begin\n            sort_counter <= sort_counter + 8'd1;\n        end\n    end\n\nendmodule